/* Adapted from josephdhahbi-svg/alice-zress-campaign/backend/dice-rules.js
 * and shortest-route pattern in Moonveil living-v17.js. No campaign state imported. */
export function resolveD20({rawRoll,modifier=0,dc}){if(!Number.isSafeInteger(rawRoll)||rawRoll<1||rawRoll>20)throw new RangeError('rawRoll must be 1..20');if(!Number.isSafeInteger(modifier)||modifier< -10||modifier>20)throw new RangeError('modifier must be -10..20');if(!Number.isSafeInteger(dc)||dc<1||dc>40)throw new RangeError('dc must be 1..40');const total=rawRoll+modifier;return Object.freeze({rawRoll,modifier,dc,total,success:total>=dc});}
export function shortestRoute(nodes,from,to){if(!nodes.some(n=>n.id===from)||!nodes.some(n=>n.id===to))return null;if(from===to)return[from];const queue=[[from]],seen=new Set([from]);while(queue.length){const route=queue.shift(),node=nodes.find(n=>n.id===route.at(-1));for(const next of node.neighbors){if(seen.has(next))continue;const path=[...route,next];if(next===to)return path;seen.add(next);queue.push(path)}}return null;}
